(ns fairy.box.web.views.icon
  (:require [clojure.string :as str]))

(defn deficon [svg]
  (fn [{class :class or {class ""}}]
    (update-in svg [1 :class]
               (fn [existing new]
                 (let [new-str (if (sequential? new)
                                 (str/join " " new)
                                 new)]
                   (str "icon " existing " " new-str))) class)))

